act-head evidence."],"evidence_refs":["roadmap/portfolio-future-architecture/companies/117_INDUSTRIAL_MAINTENANCE_DOWNTIME_INTELLIGENCE.md#sha256=958a4b4da4307e2dfe3febb1641e554db25d2c60368daceaf64c3b6151a624ec","roadmap/portfolio-future-architecture/additional-five-company-import-2026-11-03/data/AGENCY_EXECUTABLE_TASK_PROPOSALS.json#project:company:future:117:P7:gate"]}],"gates":[{"project_id":"project:company:future:117","roadmap_version":1,"gate_id":"project:company:future:117:p0:approval","satisfied":false,"evidence_refs":[]},{"project_id":"project:company:future:117","roadmap_version":1,"gate_id":"project:company:future:117:p1:approval","satisfied":false,"evidence_refs":[]},{"project_id":"project:company:future:117","roadmap_version":1,"gate_id":"project:company:future:117:p2:approval","satisfied":false,"evidence_refs":[]},{"project_id":"project:company:future:117","roadmap_version":1,"gate_id":"project:company:future:117:p3:approval","satisfied":false,"evidence_refs":[]},{"project_id":"project:company:future:117","roadmap_version":1,"gate_id":"project:company:future:117:p4:approval","satisfied":false,"evidence_refs":[]},{"project_id":"project:company:future:117","roadmap_version":1,"gate_id":"project:company:future:117:p5:approval","satisfied":false,"evidence_refs":[]},{"project_id":"project:company:future:117","roadmap_version":1,"gate_id":"project:company:future:117:p6:approval","satisfied":false,"evidence_refs":[]},{"project_id":"project:company:future:117","roadmap_version":1,"gate_id":"project:company:future:117:p7:approval","satisfied":false,"evidence_refs":[]}]}]$records$::jsonb) loop
  select * into prior from public.command_center_project_profiles where owner_id=v_owner and project_id=item->>'projectId';
  if found then
   if prior.company_id<>item->'profile'->>'company_id' or prior.source_ref<>item->>'sourceRef' or not exists(select 1 from public.command_center_specialist_brains where owner_id=v_owner and brain_key=item->'brain'->>'brain_key' and configuration_ref=item->'brain'->>'configuration_ref') then raise exception 'Company identity/source or partial import conflict: %',item->>'projectId'; end if;
   continue;
  end if;
  if exists(select 1 from public.command_center_project_profiles where owner_id=v_owner and (company_id=item->'profile'->>'company_id' or name::text=item->'profile'->>'name')) or exists(select 1 from public.command_center_canonical_entities where owner_id=v_owner and entity_id=item->>'projectId') or exists(select 1 from public.command_center_specialist_brains where owner_id=v_owner and (brain_key=item->'brain'->>'brain_key' or specialist_id=item->'brain'->>'specialist_id')) then raise exception 'Existing identity collision: %',item->>'projectId'; end if;
  insert into public.command_center_canonical_entities(owner_id,entity_id,project_id,entity_type,payload,content_hash) select x.owner_id,x.entity_id,x.project_id,x.entity_type,x.payload,x.content_hash from jsonb_populate_record(null::public.command_center_canonical_entities,item->'entity'||jsonb_build_object('owner_id',v_owner)) x;
  insert into public.command_center_project_profiles(owner_id,project_id,canonical_entity_id,type_key,company_id,name,mission,lifecycle,status,verification,priority,source_ref,stage,next_action,status_source_refs,status_observed_at) select x.owner_id,x.project_id,x.canonical_entity_id,x.type_key,x.company_id,x.name,x.mission,x.lifecycle,x.status,x.verification,x.priority,x.source_ref,x.stage,x.next_action,x.status_source_refs,x.status_observed_at from jsonb_populate_record(null::public.command_center_project_profiles,item->'profile'||jsonb_build_object('owner_id',v_owner)) x;
