  insert into public.command_center_project_checkpoints(owner_id,project_id,roadmap_version,exact_next_work_unit_id,blocker,required_environment,owner_action,verification_method,evidence_refs,resume_state_hash,created_at) select x.owner_id,x.project_id,x.roadmap_version,x.exact_next_work_unit_id,x.blocker,x.required_environment,x.owner_action,x.verification_method,x.evidence_refs,x.resume_state_hash,x.created_at from jsonb_populate_record(null::public.command_center_project_checkpoints,item->'checkpoint'||jsonb_build_object('owner_id',v_owner)) x;
